// In production, replace this with a Postgres/Sheets/API node
// pulling live hub inventory + sales history from KSKT systems.
const data = [
  { sku: 'Tomato (Local)', hub: 'Gurugram-Sec14', shelfLifeDays: 5, daysInStock: 4, unitsInStock: 240, salesHistory: [38,42,35,30,28,22,18] },
  { sku: 'Spinach (Palak)', hub: 'Gurugram-Sec14', shelfLifeDays: 3, daysInStock: 1, unitsInStock: 90, salesHistory: [30,28,32,29,31,27,33] },
  { sku: 'Potato', hub: 'Noida-Sec62', shelfLifeDays: 20, daysInStock: 6, unitsInStock: 500, salesHistory: [60,58,63,61,59,62,60] },
  { sku: 'Green Chilli', hub: 'Noida-Sec62', shelfLifeDays: 6, daysInStock: 5, unitsInStock: 70, salesHistory: [15,14,12,13,9,8,6] },
  { sku: 'Banana', hub: 'Gurugram-Sec14', shelfLifeDays: 6, daysInStock: 5, unitsInStock: 310, salesHistory: [40,39,41,38,35,30,25] }
];
return data.map(d => ({ json: d }));

const results = [];

for (const item of $input.all()) {
  const d = item.json;

  // --- spoilage risk ---
  const remainingDays = d.shelfLifeDays - d.daysInStock;
  const lifeUsedFraction = d.daysInStock / d.shelfLifeDays;
  let level;
  if (remainingDays <= 0) level = 'expired';
  else if (lifeUsedFraction >= 0.75) level = 'high';
  else if (lifeUsedFraction >= 0.5) level = 'medium';
  else level = 'low';

  // --- demand forecast (weighted moving average + trend) ---
  const sales = d.salesHistory;
  const n = sales.length;
  const weights = sales.map((_, i) => i + 1);
  const weightSum = weights.reduce((a, b) => a + b, 0);
  const weightedAvgDaily = sales.reduce((sum, u, i) => sum + u * weights[i], 0) / weightSum;
  const daysAhead = 3;
  const projectedDemand = weightedAvgDaily * daysAhead;
  const firstHalf = sales.slice(0, Math.floor(n / 2));
  const secondHalf = sales.slice(Math.floor(n / 2));
  const avg = (arr) => arr.reduce((a, b) => a + b, 0) / arr.length;
  const trendPct = ((avg(secondHalf) - avg(firstHalf)) / (avg(firstHalf) || 1)) * 100;
  const trendDirection = trendPct < -10 ? 'falling' : trendPct > 10 ? 'rising' : 'flat';

  // --- recommendation engine ---
  const surplusUnits = d.unitsInStock - projectedDemand;
  const surplusRatio = surplusUnits / d.unitsInStock;
  let action = 'hold';
  let urgency = 'none';
  if (level === 'expired') { action = 'write-off-review'; urgency = 'immediate'; }
  else if (level === 'high' && surplusRatio > 0.3) { action = trendDirection === 'falling' ? 'reallocate-to-higher-demand-hub' : 'discount-to-clear'; urgency = 'high'; }
  else if (level === 'high') { action = 'monitor-closely'; urgency = 'medium'; }
  else if (level === 'medium' && surplusRatio > 0.4) { action = 'flag-for-review'; urgency = 'low'; }

  results.push({
    json: {
      ...d,
      riskLevel: level,
      remainingDays,
      projectedDemand: Number(projectedDemand.toFixed(1)),
      trendDirection,
      action,
      urgency,
      surplusUnits: Math.round(surplusUnits)
    }
  });
}

return results;

